 const STORE='uno-app-anatomy:v1';
 const fresh=()=>({version:1,seen:[],guide:[],challenge:false,settings:{},width:390,events:[]});
 let progress=fresh();
 try {const p=JSON.parse(localStorage.getItem(STORE));if(p?.version===1){progress={...fresh(),...p};progress.seen=Array.isArray(p.seen)?p.seen.filter(x=>COMPONENTS[x]):[];progress.guide=Array.isArray(p.guide)?p.guide.filter(x=>['inspect','experiment','predict','repair'].includes(x)):[];progress.events=Array.isArray(p.events)?p.events.slice(-150):[];progress.settings=p.settings&&typeof p.settings==='object'?p.settings:{};}}catch{}
 let storageWarning=false;
 function persist(){try{localStorage.setItem(STORE,JSON.stringify(progress));}catch{if(!storageWarning){storageWarning=true;toast('Browser storage is unavailable. Progress will last for this visit only.');}}}
 function track(type,detail={}){progress.events.push({type,at:new Date().toISOString(),...detail});progress.events=progress.events.slice(-150);persist();}
